-- =====================================================================
--  Учебная база данных «Рынок IT-вакансий + коммуникации после отклика»
--  Школа Аналитиков
--  СУБД: PostgreSQL 13+
--
--
--  КАК ЗАПУСТИТЬ:
--    1. Откройте этот файл в DBeaver (File -> Open File)
--    2. Убедитесь, что сверху выбрано подключение к вашей базе
--    3. Выполните весь скрипт целиком: Alt+X  (macOS: Cmd+X)
--    4. Обновите список схем в дереве слева: F5
--    5. Проверьте загрузку последним запросом в конце файла
-- =====================================================================

DROP SCHEMA IF EXISTS hh_school CASCADE;
CREATE SCHEMA hh_school;
SET search_path = hh_school, public;


-- ---------- Регионы ----------
CREATE TABLE areas (
  area_id   INTEGER PRIMARY KEY,
  area_name TEXT NOT NULL,
  region    TEXT
);
COMMENT ON TABLE areas IS 'Регионы. Одна строка = один регион';

-- ---------- Работодатели ----------
CREATE TABLE employers (
  employer_id      INTEGER PRIMARY KEY,
  employer_name    TEXT NOT NULL,
  area_id          INTEGER REFERENCES areas (area_id),
  is_accredited_it BOOLEAN,
  employees_count  INTEGER            -- может быть NULL: численность не раскрыта
);
COMMENT ON TABLE employers IS 'Работодатели. Одна строка = одна компания';

-- ---------- Вакансии ----------
CREATE TABLE vacancies (
  vacancy_id        INTEGER PRIMARY KEY,
  employer_id       INTEGER REFERENCES employers (employer_id),
  area_id           INTEGER REFERENCES areas (area_id),
  vacancy_name      TEXT,
  professional_role TEXT,
  experience        TEXT,
  employment        TEXT,
  salary_from       INTEGER,          -- может быть NULL: зарплата не указана
  salary_to         INTEGER,          -- может быть NULL
  currency          TEXT,
  published_at      TIMESTAMP NOT NULL,
  closed_at         TIMESTAMP              -- NULL = вакансия ещё открыта
);
COMMENT ON TABLE vacancies IS 'Вакансии. Одна строка = одна вакансия';

-- ---------- Описание вакансии: связь 1:1 (есть НЕ у всех вакансий) ----------
CREATE TABLE vacancy_details (
  vacancy_id  INTEGER PRIMARY KEY REFERENCES vacancies (vacancy_id),
  description TEXT,
  key_skills  TEXT
);
COMMENT ON TABLE vacancy_details IS 'Описание вакансии. Связь 1:1 с vacancies';

-- ---------- Отклики: связь 1:N ----------
CREATE TABLE responses (
  response_id INTEGER PRIMARY KEY,
  vacancy_id  INTEGER NOT NULL REFERENCES vacancies (vacancy_id),
  resume_id   INTEGER,
  created_at  TIMESTAMP NOT NULL,
  status      TEXT CHECK (status IN ('new', 'viewed', 'invited', 'rejected'))
);
COMMENT ON TABLE responses IS 'Отклики кандидатов. Одна строка = один отклик';


