-- =====================================================================
--  ЗВОНКИ
-- =====================================================================

CREATE TABLE calls (
  call_id        INTEGER PRIMARY KEY,
  response_id    INTEGER REFERENCES responses (response_id),
  employer_id    INTEGER NOT NULL REFERENCES employers (employer_id),
  applicant_id   INTEGER NOT NULL,
  vacancy_id     INTEGER NOT NULL REFERENCES vacancies (vacancy_id),
  caller_role    TEXT NOT NULL
                 CHECK (caller_role IN ('employer', 'applicant')),
  call_duration  INTEGER
                 CHECK (call_duration IS NULL OR call_duration > 0),
  status         TEXT NOT NULL
                 CHECK (status IN ('successful', 'unsuccessful', 'error')),
  call_at        TIMESTAMP NOT NULL,
  call_tags      TEXT[] NOT NULL,
  CHECK (
    (status = 'successful' AND call_duration IS NOT NULL)
    OR
    (status IN ('unsuccessful', 'error') AND call_duration IS NULL)
  )
);

COMMENT ON TABLE calls IS
  'Звонки между работодателями и кандидатами. Одна строка = один звонок';

COMMENT ON COLUMN calls.response_id IS
  'Связанный отклик; может быть NULL';

COMMENT ON COLUMN calls.caller_role IS
  'Кто инициировал звонок: employer или applicant';

COMMENT ON COLUMN calls.call_duration IS
  'Длительность звонка в секундах';

COMMENT ON COLUMN calls.call_tags IS
  'Набор тегов звонка в формате массива';


