-- =====================================================================
--  СООБЩЕНИЯ
-- =====================================================================

CREATE TABLE messages (
  message_id      INTEGER PRIMARY KEY,
  response_id     INTEGER NOT NULL REFERENCES responses (response_id),
  vacancy_id      INTEGER NOT NULL REFERENCES vacancies (vacancy_id),
  employer_id     INTEGER NOT NULL REFERENCES employers (employer_id),
  applicant_id    INTEGER NOT NULL,
  sent_at         TIMESTAMP NOT NULL,
  sender_role     TEXT NOT NULL
                  CHECK (sender_role IN ('employer', 'applicant')),
  message_text    TEXT,
  message_meta    JSONB NOT NULL
);

COMMENT ON TABLE messages IS
  'Сообщения между работодателями и кандидатами. Одна строка = одно сообщение';

COMMENT ON COLUMN messages.sender_role IS
  'Кто отправил сообщение: employer или applicant';

COMMENT ON COLUMN messages.message_meta IS
  'Метаданные сообщения в формате JSONB';


