-- =====================================================================
--  ИНДЕКСЫ
-- =====================================================================
CREATE INDEX idx_vacancies_employer   ON vacancies (employer_id);
CREATE INDEX idx_vacancies_published  ON vacancies (published_at);
CREATE INDEX idx_responses_vacancy    ON responses (vacancy_id);
CREATE INDEX idx_responses_created    ON responses (created_at);
CREATE INDEX idx_calls_response       ON calls (response_id);
CREATE INDEX idx_calls_employer       ON calls (employer_id);
CREATE INDEX idx_calls_at             ON calls (call_at);
CREATE INDEX idx_messages_response    ON messages (response_id);
CREATE INDEX idx_messages_employer    ON messages (employer_id);
CREATE INDEX idx_messages_sent        ON messages (sent_at);

ANALYZE areas, employers, vacancies, vacancy_details, responses, calls, messages;


-- =====================================================================
--  ПРОВЕРКА ЗАГРУЗКИ
--  Ожидаемый результат:
--    areas             5
--    employers        12
--    vacancies        52
--    vacancy_details  45
--    responses       628
--    calls           251
--    messages       2862
-- =====================================================================
SELECT 'areas' AS table_name, count(*) AS rows FROM areas
UNION ALL SELECT 'employers',       count(*) FROM employers
UNION ALL SELECT 'vacancies',       count(*) FROM vacancies
UNION ALL SELECT 'vacancy_details', count(*) FROM vacancy_details
UNION ALL SELECT 'responses',       count(*) FROM responses
UNION ALL SELECT 'calls',           count(*) FROM calls
UNION ALL SELECT 'messages',        count(*) FROM messages;
